import re
def section_flattening(s):
 if not s:return None
 d={};k=re.compile(r'[a-z][a-z0-9]*(?:-[a-z0-9]+)*')
 for r in s.split(','):
  p=r.split('=',1);q=p[0].split(':') if p else []
  if len(p)!=2 or len(q)!=2 or not k.fullmatch(q[0]) or not k.fullmatch(q[1]) or not p[1] or any(ord(c)<32 or ord(c)>126 or c==',' for c in p[1]) or tuple(q) in d:return None
  d[tuple(q)]=p[1]
 return ','.join(f'{a}.{b}={d[a,b]}' for a,b in sorted(d))
